export default function next({ events, previous }) {
  let index = previous?.index ?? 0;
  if (index >= events.length)
    return { state: { index }, more: false, fileId: "unused", parent: "unused" };
  const e = events[index];
  if (!e?.fileId || !Array.isArray(e.parents) || e.parents.length !== 1)
    throw Error("Expected one source folder");
  return { state: { index: index + 1 }, more: true, fileId: e.fileId, parent: e.parents[0] };
}

