export default async function plan(
  { fileId, parent, tagId, content, acknowledge, resolution, confirmedId },
  ctx,
) {
  if (!fileId || !parent || !tagId) throw Error("Configure file and folders and tag");
  if (typeof content !== "string" || new TextEncoder().encode(content).length > 524288)
    throw Error("Workflow file exceeds 512 KiB");
  let full;
  try {
    full = JSON.parse(content);
  } catch {
    throw Error("Invalid JSON workflow");
  }
  full = full.data ?? full;
  if (
    !full.name ||
    !Array.isArray(full.nodes) ||
    !full.connections ||
    typeof full.connections !== "object"
  )
    throw Error("Invalid workflow export");
  let settings = {};
  for (const k of ["executionOrder", "timezone"])
    if (full.settings?.[k]) settings[k] = full.settings[k];
  const body = { name: full.name, nodes: full.nodes, connections: full.connections, settings };
  const key = "n8n-import:" + fileId;
  let s = await ctx.state.get(key);
  if (!s) s = { phase: "create-ready", body: JSON.stringify(body), parent, tagId };
  if (s.body !== JSON.stringify(body) || s.parent !== parent || s.tagId !== tagId)
    throw Error("Restore original file and configuration");
  if (s.phase.endsWith("-pending")) {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect " + s.phase + " " + key);
    const phase = s.phase.slice(0, -8);
    if (resolution === "absent") s.phase = phase + "-ready";
    else {
      if (phase === "create") {
        if (!confirmedId) throw Error("Enter confirmed workflow ID");
        s.workflowId = confirmedId;
      }
      s.phase = phase === "create" ? "tag-ready" : phase === "tag" ? "move-ready" : "done";
    }
  }
  let action = s.phase.endsWith("-ready") ? s.phase.slice(0, -6) : "done";
  if (action !== "done") {
    s.phase = action + "-pending";
    await ctx.state.set(key, s);
  } else await ctx.state.set(key, s);
  return {
    key,
    action,
    body,
    workflowId: s.workflowId ?? "pending",
    fileId,
    parent,
    tagIds: [tagId],
  };
}

