export default async function confirm({ key, phase, result, fileId, tagId, destination }, ctx) {
  const s = await ctx.state.get(key);
  if (s?.phase !== phase + "-pending") throw Error("Unexpected checkpoint");
  if (phase === "create") {
    if (!(result.status >= 200 && result.status < 300 && result.body?.id))
      throw Error("Inspect n8n create");
    s.workflowId = String(result.body.id);
  }
  if (phase === "tag" && !result.tags?.some((t) => t.id === tagId)) throw Error("Inspect tags");
  if (phase === "move" && (result.id !== fileId || !result.parents?.includes(destination)))
    throw Error("Inspect Drive move");
  s.phase = phase === "create" ? "tag-ready" : phase === "tag" ? "move-ready" : "done";
  await ctx.state.set(key, s);
  return { ok: true };
}

